#!/usr/bin/env node
(async () => {
const fs = (await import('node:fs')).default
const path = (await import('node:path')).default
const root = path.dirname(path.resolve(process.argv[1]))
const FILES = {"public/images/casual.png":"","public/images/detail-1.png":"","public/images/detail-2.png":"","public/images/detail-3.png":"","public/images/detail-4.png":"","public/images/formal.png":"","public/images/gym.png":"","public/images/hero.png":"","public/images/p1.png":"","public/images/p10.png":"","public/images/p11.png":""}
for (const [rel, b64] of Object.entries(FILES)) {
  const dest = path.join(root, rel)
  if (fs.existsSync(dest) && !process.argv.includes('--force')) continue
  fs.mkdirSync(path.dirname(dest), { recursive: true })
  fs.writeFileSync(dest, Buffer.from(b64, 'base64'))
}
console.log('images-1: 11 images ready')
})().catch((e) => { console.error(e); process.exit(1) })
